<script setup>
import {ref,computed} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {useAuthStore} from '../stores/auth'
import api from '../services/api'
const router=useRouter(),route=useRoute(),auth=useAuthStore(),register=computed(()=>route.name==='register')
const fullName=ref(''),username=ref(''),email=ref(''),password=ref(''),error=ref(''),info=ref(''),busy=ref(false)
async function submit(){busy.value=true;error.value='';info.value='';try{
 if(register.value){await api.post('/register',{fullName:fullName.value,username:username.value,email:email.value,password:password.value});info.value='Conta criada. Faça login para continuar.';await router.push({name:'login',query:{...route.query,registered:'1'}});return}
 const result=await api.post('/login',{email:email.value,password:password.value});auth.setAuth(result.token,result.user)
 const redirect=typeof route.query.redirect==='string'&&route.query.redirect.startsWith('/')&&!route.query.redirect.startsWith('//')?route.query.redirect:'/meus-ingressos'
 await router.push(redirect)
}catch(e){error.value=e.message||'Não foi possível concluir.'}finally{busy.value=false}}
</script>
<template><div class="container auth-layout"><div class="auth-welcome"><div class="eyebrow">✦ BEM-VINDO AO ALFRED</div><h1>Tem muita coisa boa <em>esperando por você.</em></h1><p>Entre para organizar suas experiências e salvar suas simulações de reserva.</p><div class="auth-abstract">✳</div></div><div class="auth-card"><span class="kicker">SUA CONTA</span><h2>{{register?'Começar por aqui.':'Que bom te ver de novo.'}}</h2><p>{{register?'Crie sua conta para acompanhar seus eventos.':'Acesse sua conta para continuar.'}}</p><div v-if="route.query.registered" class="notice-success" role="status">Cadastro realizado. Entre com seus dados.</div><form @submit.prevent="submit"><template v-if="register"><label for="fullName" class="field-label">Nome completo</label><input id="fullName" v-model="fullName" class="form-control" maxlength="120" required/><label for="username" class="field-label">Usuário</label><input id="username" v-model="username" class="form-control" minlength="3" maxlength="40" pattern="[A-Za-z0-9_]+" required/></template><label for="email" class="field-label">E-mail</label><input id="email" v-model="email" type="email" class="form-control" required/><label for="password" class="field-label">Senha</label><input id="password" v-model="password" type="password" class="form-control" :minlength="register?8:1" required/><button class="button button-primary button-full" :disabled="busy">{{busy?'Aguarde...':register?'Criar minha conta':'Entrar'}} ↗</button><div v-if="error" class="notice-error" role="alert">{{error}}</div><div v-if="info" class="notice-success" role="status">{{info}}</div></form><p class="auth-swap" v-if="register">Já tem conta? <router-link :to="{name:'login',query:route.query}">Entrar</router-link></p><p class="auth-swap" v-else>Ainda não tem uma conta? <router-link :to="{name:'register',query:route.query}">Cadastrar</router-link></p><small class="help-text">O cadastro precisa de uma API Alfred ativa e um banco de dados configurado.</small></div></div></template>
